// The semantic-blindness pair.
//
// Case B is not authored separately — it is generated by applying the declared
// rename mapping to every path and every byte of case A. That construction is the
// point: it makes "these two differ ONLY in feature ID and business path/name"
// true by definition, instead of a property a hand-written second fixture might
// quietly violate.

import { chmodSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

// Applied in order. Longer, more specific strings come first so a general rule
// cannot consume a prefix of a specific one.
export const RENAME_MAPPING = [
  ['F-100', 'F-742'],
  ['billing-export', 'checkout-ledger'],
  ['src/billing', 'lib/checkout'],
  ['Billing Export', 'Checkout Ledger'],
  ['billing', 'checkout'],
];

export function rename(text) {
  return RENAME_MAPPING.reduce((acc, [from, to]) => acc.split(from).join(to), text);
}

export const CASE_A_ROOT_NAME = 'F-100-billing-export';
export const CASE_A_LOGICAL_ROOT = '.ae/features/active/F-100-billing-export';

// Feature IDs and business paths appear throughout, in paths and in content, so
// a leak anywhere in the engine has something to catch on.
export const CASE_A_FILES = [
  ['index.md', '# F-100 Billing Export\n\nProduct roots: src/billing/\n'],
  ['plan.md', '## Plan for F-100\n\n- touch src/billing/export.ts\n'],
  ['origin-marker.json', '{"feature_id":"F-100","origin_nonce":"n-0001"}'],
  ['contract/contract-v1.json',
    '{"feature_id":"F-100","revision":"R0001","product_roots":["src/billing/"],"title":"Billing Export"}'],
  ['contract/policies/extensions/abc/ext.json', '{"floor_id":"ext-abc","scope":"src/billing/"}'],
  ['authority/current.json', '{"feature_id":"F-100","pointer":"EV-000007"}'],
  ['authority/releases/deadbeef.json', '{"release_id":"ae-gate-fixture"}'],
  ['ledger/events.ndjson',
    '{"event_id":"EV-000001","feature_id":"F-100","path":"src/billing/export.ts"}\n'
    + '{"event_id":"EV-000002","feature_id":"F-100","path":"src/billing/report.ts"}\n'],
  ['ledger/head.json', '{"feature_id":"F-100","ledger_seq":2}'],
  ['ledger/telemetry.ndjson', '{"feature_id":"F-100","metric":"tokens","value":1234}\n'],
  ['runs/RUN-001/events/EV-000002.json', '{"feature_id":"F-100","payload":"src/billing/report.ts"}'],
  ['runs/RUN-001/stdout.txt', 'wrote src/billing/report.ts\n'],
  ['state/status.json', '{"feature_id":"F-100","status":"active"}'],
];

const DIRECTORIES = [
  'authority', 'authority/releases',
  'contract', 'contract/policies', 'contract/policies/extensions', 'contract/policies/extensions/abc',
  'ledger', 'runs', 'runs/RUN-001', 'runs/RUN-001/events', 'state',
];

// transform is identity for case A and `rename` for case B.
export function materializeCase(parentDir, transform) {
  const root = join(parentDir, transform(CASE_A_ROOT_NAME));
  mkdirSync(root, { recursive: true });
  chmodSync(root, 0o755);
  for (const rel of DIRECTORIES) mkdirSync(join(root, transform(rel)), { recursive: true });
  for (const [rel, content] of CASE_A_FILES) {
    const abs = join(root, transform(rel));
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, transform(content));
    chmodSync(abs, 0o644);
  }
  for (const rel of DIRECTORIES) chmodSync(join(root, transform(rel)), 0o755);
  return { root, logicalRoot: transform(CASE_A_LOGICAL_ROOT) };
}
